contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 role, address account) public {
        bool callerIsAccount = (account == address(this));
        bool before = c.hasRole(role, account);

        bool reverted;
        try c.renounceRole(role, account) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.hasRole(role, account);

        assert(reverted == !callerIsAccount && (reverted || after == false));
    }
}

